mapper.select:
SELECT nsr.id AS reqId, nsr.title AS reqTitle, nsr.requester AS requester, nsr.req_dept AS reqDept, nsr.req_date AS reqDate, nrt.category AS category, nsr.status AS statusCode FROM newbie_request_todo nrt INNER JOIN newbie_sample_request nsr ON nrt.req_id = nsr.id
WHERE nsr.status = #{status}
WHERE nrt.category = #{category}
AND nsr.is_deleted = 0 AND nrt.is_deleted = 0 ORDER BY nsr.status asc, nsr.req_date desc
